\title{On the Conversion of LaTeX to Word}
\author{A. Researcher}
\date{2026}
\maketitle
\begin{abstract}
We present a converter producing native OMML and live fields.
\end{abstract}
\section{Introduction}\label{sec:intro}

Consider a function $f : \mathbb{R}^n \to \mathbb{R}$ with gradient $\nabla f$.\footnote{The gradient is the vector of partial derivatives.} As shown in \eqref{eq:energy}, mass and energy are equivalent.

\begin{equation}
E = mc^2
\label{eq:energy}
\end{equation}

\begin{theorem}[Triangle inequality]
\label{thm:tri}
For all $x, y$, $\left\| x + y \right\| \leq \left\| x \right\| + \left\| y \right\|$.
